// dates.js.
const MS_PER_DAY = 86_400_000;           // private: not exported.
export function parse(text) { return new Date(`${text}T00:00:00Z`); }
export function format(date) { return date.toISOString().slice(0, 10); }
export function daysBetween(a, b) { return Math.round((b - a) / MS_PER_DAY); }

// streak.js.
import { parse, daysBetween } from "./dates.js";
export function streakLength(first, last) {
  return daysBetween(parse(first), parse(last)) + 1;
}
```

| Form | Rule |
|---|---|
| `export function x`. | named; import as `{ x }`. |
| `export default ...`. | one per module; import as any name. |
| `import { x as y }`. | rename a named import locally. |
| `import * as dates`. | namespace object of all named exports. |
| not exported. | private to the module. |

